SELECT
    SUM(wrd.receive_qty) receive_qty
FROM warehouse_receive_detail wrd
INNER JOIN warehouse_receive wr ON wrd.main_id = wr.id AND wrd.is_deleted = FALSE
WHERE wr.is_deleted = FALSE and wr.invalid_status = FALSE

